L33_1 = "\237\129\172\236\156\188\226\128\166\226\128\166! \235\176\150\236\151\144 \235\130\152\236\152\164\235\138\148 \234\177\180 \236\139\171\236\167\128\235\167\140 \236\151\176\234\181\172\236\134\140\235\167\140\237\129\188\236\157\128 \237\149\152\235\163\168\236\151\144 \236\151\180\235\145\144 \235\178\136\236\148\169\236\157\180\235\157\188\235\143\132 \234\176\136 \237\133\144\235\141\176!"
