L32_1.m_fTalkTime = 0.03
L33_1 = "\227\129\143\227\129\163\226\128\166\226\128\166\239\188\129\227\128\128\229\164\150\229\135\186\227\129\175\229\171\140\227\129\132\227\129\160\227\129\145\227\129\169\227\128\129\231\160\148\231\169\182\230\137\128\227\129\160\227\129\145\227\129\175\228\189\149\229\155\158\227\129\167\227\130\130\232\161\140\227\129\141\227\129\159\227\129\132\239\188\129"
