L33_1 = "\229\145\131\226\128\166\226\128\166\239\188\129\230\136\145\230\152\175\228\184\141\229\150\156\230\173\161\229\164\150\229\135\186\229\149\166\239\188\140\228\189\134\231\160\148\231\169\182\229\174\164\231\154\132\232\169\177\228\184\128\229\164\169\229\142\187\229\128\13912\230\172\161\228\185\159\230\178\146\229\149\143\233\161\140\239\188\129"
L32_1.m_Talk_TWN = L33_1
L33_1 = "\229\146\179\226\128\166\226\128\166\239\188\129\230\136\145\232\153\189\231\132\182\228\184\141\229\150\156\230\172\162\229\164\150\229\135\186\239\188\140\228\189\134\231\160\148\231\169\182\230\137\128\231\154\132\232\175\157\228\184\128\229\164\169\229\143\175\228\187\165\229\142\18712\230\172\161\239\188\129"
