L34_1 = "\227\129\157\227\129\134\227\129\157\227\129\134\227\128\130\230\149\153\230\142\136\227\129\139\227\130\137\229\144\141\229\137\141\227\130\146\232\129\158\227\129\139\227\130\140\227\129\159\227\129\168\227\129\141\227\129\171\227\130\162\227\131\171\227\131\134\227\130\163\227\129\140\227\129\153\227\129\148\227\129\143\229\164\167\227\129\141\227\129\170\229\163\176\227\129\167\231\173\148\227\129\136\227\129\159\227\129\139\227\130\137\227\129\179\227\129\163\227\129\143\227\130\138\227\129\151\227\129\161\227\130\131\227\129\163\227\129\159\227\128\130"
