L33_1.m_Talk_TWN = L34_1
L34_1 = "\230\178\161\233\148\153\227\128\130\230\149\153\230\142\136\233\151\174\229\136\176\229\144\141\229\173\151\231\154\132\230\151\182\229\128\153\239\188\140\229\176\177\233\152\191\229\176\148\231\188\135\229\155\158\231\173\148\229\190\151\233\157\158\229\184\184\229\164\167\229\163\176\239\188\140\229\144\147\228\186\134\230\136\145\228\184\128\229\164\167\232\183\179\227\128\130"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ja. Als die Professorin Arti nach ihrem Namen gefragt hat, waren wir alle \195\188berrascht, dass sie so laut geantwortet hat."
