L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "\231\132\161\230\132\143\229\145\179\227\129\170\228\184\141\232\137\175\229\147\129\227\129\168\232\168\128\227\130\143\227\130\140\227\129\166\227\128\129\229\133\168\233\131\168\227\129\190\227\129\168\227\130\129\227\129\166\230\141\168\227\129\166\227\130\137\227\130\140\227\129\161\227\130\131\227\129\163\227\129\159\227\130\147\227\129\160\227\129\145\227\129\169\226\128\166\226\128\166\231\167\129\227\129\160\227\129\145\227\129\175\227\130\171\227\130\166\227\131\179\227\130\191\227\131\188\227\129\171\227\129\170\227\129\163\227\129\166\231\148\159\227\129\141\229\187\182\227\129\179\227\129\159\227\128\130"
