L33_1.m_Talk_TWN = L34_1
L34_1 = "\230\136\145\228\187\172\232\162\171\231\167\176\228\184\186\230\175\171\230\151\160\230\132\143\228\185\137\231\154\132\230\174\139\230\172\161\229\147\129\239\188\140\228\184\128\232\181\183\232\162\171\228\184\162\229\188\131\228\186\134\226\128\166\226\128\166\228\189\134\230\136\145\230\136\144\228\184\186\228\186\134\229\136\182\232\163\129\232\128\133\230\180\187\228\186\134\228\184\139\230\157\165\227\128\130"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Die meisten von ihnen wurden entsorgt, weil sie defekt und somit nutzlos waren ... aber ich wurde ein Counter und konnte daher \195\188berleben."
