L34_1.m_fTalkTime = 0.03
L35_1 = "\227\129\167\227\130\130\227\128\129\227\129\157\227\129\147\227\129\190\227\129\167\227\129\160\227\129\163\227\129\159\227\130\143\227\128\130\231\167\129\227\129\159\227\129\161\227\130\146\228\189\156\227\130\138\229\135\186\227\129\151\227\129\159\227\129\130\227\129\174\228\186\186\227\129\159\227\129\161\227\129\139\227\130\137\227\129\153\227\130\140\227\129\176\227\128\129\231\167\129\227\129\175\229\164\177\230\149\151\228\189\156\227\129\171\227\129\153\227\129\142\227\129\170\227\129\139\227\129\163\227\129\159\227\128\130"
L34_1.m_Talk_JPN = L35_1
L35_1 = "But that was it. Because in the eyes of the people who made us, I was still a defect."
