L35_1 = "\228\184\141\233\129\142\233\128\153\228\185\159\229\143\170\230\152\175\230\136\145\232\135\170\232\170\141\231\130\186\232\128\140\229\183\178\239\188\140\229\156\168\229\137\181\233\128\160\230\136\145\229\128\145\231\154\132\228\186\186\231\156\188\232\163\161\231\156\139\228\190\134\239\188\140\230\136\145\233\130\132\230\152\175\229\128\139\229\164\177\230\149\151\229\147\129\227\128\130"
L34_1.m_Talk_TWN = L35_1
L35_1 = "\228\189\134\228\187\133\230\173\164\232\128\140\229\183\178\227\128\130\229\156\168\229\136\155\233\128\160\230\136\145\228\187\172\231\154\132\228\186\186\231\156\139\230\157\165\239\188\140\230\136\145\228\187\141\230\152\175\229\164\177\232\180\165\229\147\129\227\128\130"
