L2_1.m_Talk_TWN = L3_1
L3_1 = "\233\130\163\230\151\182\231\154\132\229\164\169\231\169\186\229\176\177\229\131\143\231\142\176\229\156\168\228\184\128\230\160\183\227\128\130\230\136\145\232\162\171\229\165\185\230\138\177\229\156\168\230\128\128\233\135\140\239\188\140\229\164\180\228\184\128\230\172\161\231\156\139\229\136\176\228\186\134\232\191\153\228\184\170\228\184\150\231\149\140\227\128\130"
L2_1.m_Talk_SCN = L3_1
